require __DIR__.'/../inc/bootstrap.php';$id=(int)($_GET['id']??0);$stmt=$db->prepare('SELECT * FROM application_files WHERE id=?');$stmt->execute([$id]);$file=$stmt->fetch();if(!$file){http_response_code(404);exit('File not found.');}$path=UPLOAD_PATH.'/'.$file['stored_name'];if(!is_file($path)){http_response_code(404);exit('File not found.');}header('Content-Type: '.($file['mime_type']?:'application/octet-stream'));header('Content-Length: '.filesize($path));header('Content-Disposition: attachment; filename="'.str_replace(['"',"\r","\n"],'',basename($file['original_name'])).'"');header('X-Content-Type-Options: nosniff');readfile($path);exit;
